diff --git a/mail/components/extensions/annotations/includes/messages/decodeBinaryString.js b/mail/components/extensions/annotations/includes/messages/decodeBinaryString.js
new file mode 100644
index 00000000000..a1d92c11b78
--- /dev/null
+++ b/mail/components/extensions/annotations/includes/messages/decodeBinaryString.js
@@ -0,0 +1,13 @@
+/**
+ * Decodes a binary string using the given encoding format and returns a
+ * JavaScript string. Produces mangled output if used with anything but a binary
+ * input string.
+ */
+function decodeBinaryString(binaryString, inputEncoding = "utf-8") {
+  const buffer = new Uint8Array(binaryString.length);
+  for (let i = 0; i < binaryString.length; i++) {
+    buffer[i] = binaryString.charCodeAt(i) & 0xff;
+  }
+  const decoder = new TextDecoder(inputEncoding);
+  return decoder.decode(buffer);
+}
